const NOW = new Date(2026, 7, 9, 10, 0, 0)
const MIDNIGHT_AUG_10 = new Date(2026, 7, 10, 0, 0, 0).getTime()
const MIDNIGHT_AUG_11 = new Date(2026, 7, 11, 0, 0, 0).getTime()

interface UpdateStub {
  version: string
  date: string
  body: string
  download: ReturnType<typeof vi.fn>
  install: ReturnType<typeof vi.fn>
  close: ReturnType<typeof vi.fn>
}

/**
 * Stand-in for the Tauri `Update` resource. A fresh object per `check()` call
 * mirrors the plugin, which mints a new Rust resource every time.
 */
interface StubBehaviour {
  download?: ReturnType<typeof vi.fn>
  install?: ReturnType<typeof vi.fn>
  close?: ReturnType<typeof vi.fn>
}

const makeUpdate = (version: string, behaviour: StubBehaviour = {}): UpdateStub => ({
  version,
  date: '2026-08-09',
  body: `Jupiter Desktop v${version}`,
  download: behaviour.download ?? vi.fn().mockResolvedValue(undefined),
  install: behaviour.install ?? vi.fn().mockResolvedValue(undefined),
  close: behaviour.close ?? vi.fn().mockResolvedValue(undefined),
})

/** Every stub handed out by `check()`, newest last. */
const handedOut: UpdateStub[] = []

const servesUpdate = (version: string, behaviour: StubBehaviour = {}): void => {
  checkMock.mockImplementation(async () => {
    const update = makeUpdate(version, behaviour)
    handedOut.push(update)
    return update
  })
}

const advance = async (ms: number): Promise<void> => {
  await act(async () => {
    await vi.advanceTimersByTimeAsync(ms)
  })
}

/**
 * Step forward a second at a time until `reached()` holds.
 *
 * Scheduler ticks fire at whole-minute offsets from mount, not from the end of
 * the previous advance, so a single long jump lands past the tick and cannot
 * tell you when it happened. Stepping stops the clock on the tick itself.
 */
const advanceUntil = async (reached: () => boolean, maxSeconds = 120): Promise<void> => {
  for (let step = 0; step < maxSeconds && !reached(); step += 1) {
    await advance(1000)
  }
}

/**
 * Assert that a full warning is running.
 *
 * The countdown is set on a scheduler tick and read up to one tick later, so
 * from the observation point the full five minutes always reads as "nearly
 * five". What matters is that it is a fresh countdown, not a stub of one.
 */
const expectFullCountdown = (restartAt: number | null): void => {
  const remaining = (restartAt ?? 0) - Date.now()
  expect(remaining).toBeGreaterThan(WARNING_MS - TICK_MS)
  expect(remaining).toBeLessThanOrEqual(WARNING_MS)
}

/**
 * Mount the hook with a session open, let the first check find nothing, then
 * let the hourly check find `version` and plan its restart. Leaves the flow in
 * `scheduled`.
 *
 * The session is what puts the flow on the nightly path at all: with nobody
 * logged in an update applies on the spot, whichever check finds it.
 */
const arrangeScheduledUpdate = async (version = '1.2.11') => {
  useGanymedeStore.setState({ isAuthenticated: true })
  checkMock.mockResolvedValue(null)
  const hook = renderHook(() => useUpdater())
  await advance(STARTUP_DELAY_MS)

  servesUpdate(version)
  await advance(HOUR_MS)

  return hook
}

describe('nextLocalMidnight', () => {
  it('returns the next local 00:00', () => {
    expect(nextLocalMidnight(new Date(2026, 7, 9, 10, 30, 0))).toBe(MIDNIGHT_AUG_10)
  })

  it('rolls over the end of the month', () => {
    expect(nextLocalMidnight(new Date(2026, 7, 31, 23, 59, 0))).toBe(
      new Date(2026, 8, 1, 0, 0, 0).getTime()
    )
  })

  it('moves a midnight to the midnight after it', () => {
    expect(nextLocalMidnight(new Date(MIDNIGHT_AUG_10))).toBe(MIDNIGHT_AUG_11)
  })

  // The suite runs in Europe/Rome (see vitest.config.ts) so these two mean
  // something. Under a UTC runner both hold for any implementation.
  it('lands on local midnight, not UTC midnight', () => {
    const result = new Date(nextLocalMidnight(new Date(2026, 7, 9, 10, 30, 0)))
    expect(result.getHours()).toBe(0)
    expect(result.getMinutes()).toBe(0)
  })

  it('crosses a 23-hour day without drifting an hour', () => {
    // Clocks go forward on 2026-03-29 in Europe/Rome, so that day is 23 hours
    // long and a plain "+24h" lands on 01:00 instead of midnight.
    const result = new Date(nextLocalMidnight(new Date(2026, 2, 29, 0, 0, 0)))
    expect(result.getTime()).toBe(new Date(2026, 2, 30, 0, 0, 0).getTime())
    expect(result.getHours()).toBe(0)
  })
})

