/**
 * Midnight at the start of the day after `from`, in local time.
 *
 * Built through the local-time `Date` constructor so the runtime resolves DST
 * transitions: on a 23-hour day the result is still the next local 00:00, not
 * `from + 24h`.
 */
export const nextLocalMidnight = (from: Date): number =>
  new Date(from.getFullYear(), from.getMonth(), from.getDate() + 1, 0, 0, 0, 0).getTime()

/**
 * Release an update handle without ever throwing.
 *
 * Closing is always bookkeeping, never the point of the call. A throw escaping
 * here would land in a caller's catch and be mistaken for the operation itself
 * failing -- which, on the supersede path, would discard a perfectly good
 * downloaded package.
 */
const releaseHandle = async (update: TauriUpdate): Promise<void> => {
  try {
    await update.close()
  } catch (error) {
    console.warn('[Updater] Failed to release update handle:', error)
  }
}

/** Release the Rust-side resource of an update we are not going to install. */
const discardPending = async (): Promise<void> => {
  const update = pendingUpdate
  pendingUpdate = null
  if (update) await releaseHandle(update)
}

/** Transfer the package, reporting progress into the store. */
const downloadPending = async (update: TauriUpdate, surfaced: boolean): Promise<void> => {
  useGanymedeStore.getState().setUpdateDownloading(toUpdateInfo(update), surfaced)

  let totalDownloaded = 0
  let contentLength = 0

  await update.download((event) => {
    if (event.event === 'Started') {
      contentLength = event.data.contentLength ?? 0
    } else if (event.event === 'Progress') {
      totalDownloaded += event.data.chunkLength
      const progress = contentLength > 0 ? Math.round((totalDownloaded / contentLength) * 100) : 0
      useGanymedeStore.getState().setUpdateProgress(progress)
    }
    // 'Finished' event doesn't need special handling
  })
}

interface ApplyOptions {
  /**
   * Abandon the install if a session opened in the meantime. Set on the
   * pre-login path, whose whole premise is that no session exists yet.
   */
  onlyWhileLoggedOut?: boolean
  /** Whether a failure is the user's business or just the log's. */
  surfaceErrors?: boolean
}

/**
 * Announce the restart and hand over to the installer.
 *
 * `install()` does not return: it spawns the NSIS installer and exits the
 * process. Anything that must happen before the app dies happens here.
 */
const applyUpdate = async (options: ApplyOptions = {}): Promise<void> => {
  const { onlyWhileLoggedOut = false, surfaceErrors = false } = options
  const store = useGanymedeStore.getState()
  const update = pendingUpdate

  if (!update) {
    console.warn('[Updater] Restart requested with no update downloaded')
    store.setUpdateIdle()
    return
  }

  store.setUpdateInstalling()
  console.log('[Updater] Installing', update.version)

  // Urgent: this is the last thing the user is told before the process dies,
  // and a coalescer drop would make the app vanish with no explanation at all.
  await sendUrgentNativeNotification({
    title: 'Jupiter Desktop',
    body: `Installing version ${update.version}. The app restarts in a few seconds.`,
  })
  await new Promise((resolve) => setTimeout(resolve, TOAST_TO_INSTALL_DELAY_MS))

  // Last possible moment to back out. Those few seconds of grace are exactly
  // when someone staring at the login form finishes typing their password.
  if (onlyWhileLoggedOut && useGanymedeStore.getState().isAuthenticated) {
    const restartAt = nextLocalMidnight(new Date())
    useGanymedeStore.getState().setUpdateScheduled(restartAt)
    console.log('[Updater] Session opened during the grace period; restart deferred to the night')
    return
  }

  try {
    await update.install()
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Installation failed'
    console.error('[Updater] Install failed:', message)
    // Release it: the package is a full installer held in the webview's
    // resource table, and the hourly check will download a fresh one.
    await discardPending()
    useGanymedeStore.getState().setUpdateError(message, surfaceErrors)
  }
}

/**
 * Swap in a newer build for one already downloaded and waiting.
 *
 * The replacement is transferred before the incumbent is released: a failure
 * here must cost nothing, because the package being replaced is a verified one
 * that is ready to install tonight. Losing it to a dropped connection would
 * push the restart a full day.
 */
const supersedePending = async (
  update: TauriUpdate,
  previous: { info: UpdateInfo | null; restartAt: number; surfaced: boolean }
): Promise<void> => {
  console.log('[Updater] Superseding pending', previous.info?.version, 'with', update.version)

  try {
    await downloadPending(update, previous.surfaced)
  } catch (error) {
    console.warn('[Updater] Replacement download failed; keeping the pending update:', error)
    await releaseHandle(update)
    useGanymedeStore
      .getState()
      .restoreScheduled(previous.info, previous.restartAt, previous.surfaced)
    return
  }

  const superseded = pendingUpdate
  pendingUpdate = update
  if (superseded) await releaseHandle(superseded)

  // A newer build is not a reason to undo a postponement: the user said
  // "not tonight" about the restart, not about a particular version.
  useGanymedeStore.getState().setUpdateScheduled(previous.restartAt)
}

/**
 * One automatic check.
 *
 * Stays silent by construction: it never reports errors on screen, and once a
 * session is open it never puts anything on screen at all.
 */
const runAutoCheck = async (): Promise<void> => {
  const { updateFlowBusy, updatePhase: phaseBeforeCheck } = useGanymedeStore.getState()
  if (updateFlowBusy) return
  if (phaseBeforeCheck === 'warning' || phaseBeforeCheck === 'installing') return

  useGanymedeStore.getState().setUpdateFlowBusy(true)
  let owned: TauriUpdate | null = null

  try {
    const { check } = await import('@tauri-apps/plugin-updater')
    const update = (await check()) as TauriUpdate | null

    if (!update) {
      console.log('[Updater] No updates available')
      return
    }

    // Re-read: the check is a network round trip, and the countdown may have
    // opened while it was in flight.
    const { updatePhase, updateInfo, updateRestartAt, updateSurfaced } =
      useGanymedeStore.getState()

    if (updatePhase === 'warning' || updatePhase === 'installing') {
      await releaseHandle(update)
      return
    }

    // A restart is already planned: the only news worth acting on is a build
    // newer than the one sitting in memory.
    if (updatePhase === 'scheduled') {
      if (update.version === updateInfo?.version) {
        await releaseHandle(update)
        return
      }

      await supersedePending(update, {
        info: updateInfo,
        restartAt: updateRestartAt ?? nextLocalMidnight(new Date()),
        surfaced: updateSurfaced,
      })
      return
    }

    // Nothing should be held at this point, but releasing first means a stray
    // handle can never be orphaned by the assignment below.
    await discardPending()
    owned = update
    pendingUpdate = update
    console.log('[Updater] Update available:', update.version)

    // The login screen is the one moment a restart costs nothing, so an update
    // found while it is up applies on the spot. Anywhere else it waits.
    const loggedOut = !useGanymedeStore.getState().isAuthenticated

    await downloadPending(update, loggedOut)

    // Re-read after the transfer: on a slow link the session can come up while
    // the package is still coming down.
    if (loggedOut && !useGanymedeStore.getState().isAuthenticated) {
      await applyUpdate({ onlyWhileLoggedOut: true })
      return
    }

    const restartAt = nextLocalMidnight(new Date())
    useGanymedeStore.getState().setUpdateScheduled(restartAt)
    console.log('[Updater] Restart planned for', new Date(restartAt).toISOString())
  } catch (error) {
    console.error('[Updater] Automatic check failed:', error)
    // Tear down only what this pass created. A package downloaded earlier is
    // still good, still scheduled, and none of this pass's business.
    if (owned && pendingUpdate === owned) {
      await discardPending()
      useGanymedeStore.getState().setUpdateIdle()
    }
  } finally {
    useGanymedeStore.getState().setUpdateFlowBusy(false)
  }
}

/** Chained rather than an interval, so a slow check cannot overlap the next. */
const scheduleAutoCheck = (delayMs: number): void => {
  if (checkTimer !== null) clearTimeout(checkTimer)
  checkTimer = setTimeout(async () => {
    await runAutoCheck()
    scheduleAutoCheck(AUTO_CHECK_INTERVAL_MS)
  }, delayMs)
}

/**
 * Make the imminent restart impossible to miss.
 *
 * At the planned hour the window is normally hidden in the tray, so the in-app
 * countdown -- and with it "Restart now" and "Postpone" -- is out of reach. The
 * window is raised so those controls exist at all, and the toast goes out
 * through the urgent path: the coalescer is tuned for trade bursts and caps a
 * flush at five, and local midnight is exactly when such a burst happens.
 */
const announceRestart = async (version: string): Promise<void> => {
  const delivered = await sendUrgentNativeNotification({
    title: 'Jupiter Desktop',
    body: `Restarting in 5 minutes to apply version ${version}.`.trim(),
  })

  if (!delivered) {
    console.warn('[Updater] Restart toast not delivered; falling back to the in-app countdown')
  }

  if (!isTauri()) return

  try {
    const { getCurrentWindow } = await import('@tauri-apps/api/window')
    const appWindow = getCurrentWindow()
    await appWindow.show()
    await appWindow.setFocus()
  } catch (error) {
    console.warn('[Updater] Failed to raise the window for the restart warning:', error)
  }
}

/** Open the final countdown and tell the user about it. */
const openWarning = (version: string): void => {
  const restartAt = Date.now() + RESTART_WARNING_MS
  useGanymedeStore.getState().setUpdateWarning(restartAt)
  console.log('[Updater] Restart warning issued for', new Date(restartAt).toISOString())
  void announceRestart(version)
}

/**
 * Drives `scheduled -> warning -> installing` off the wall clock.
 *
 * The countdown always runs its full length, measured from the tick that opens
 * it, and a countdown found long past its deadline is restarted rather than
 * honoured: a machine that slept through it never showed anyone anything.
 */
const runSchedulerTick = (): void => {
  const { updatePhase, updateRestartAt, updateInfo } = useGanymedeStore.getState()

  if (updateRestartAt === null) return
  const now = Date.now()
  const version = updateInfo?.version ?? ''

  if (updatePhase === 'scheduled' && now >= updateRestartAt - RESTART_WARNING_MS) {
    openWarning(version)
    return
  }

  if (updatePhase === 'warning' && now >= updateRestartAt) {
    if (now - updateRestartAt > STALE_WARNING_MS) {
      console.log('[Updater] Countdown expired unseen (clock jump or sleep); restarting it')
      openWarning(version)
      return
    }
    void applyUpdate()
  }
}

export function useUpdater(): UseUpdaterReturn {
  const state = useGanymedeStore(
    useShallow((s) => ({
      phase: s.updatePhase,
      progress: s.updateProgress,
      updateInfo: s.updateInfo,
      restartAt: s.updateRestartAt,
      surfaced: s.updateSurfaced,
      error: s.updateError,
    }))
  )

  // Start the automatic check loop and the restart scheduler. Guarded so one
  // pair runs for the whole app, not one per consumer. They are never torn
  // down: both are app-lived and only ever write to the store, never to
  // component state.
  useEffect(() => {
    if (!isTauri()) return
    if (useGanymedeStore.getState().updateAutoCheckStarted) return

    // must not schedule its own loop.
    useGanymedeStore.getState().markUpdateAutoCheckStarted()
    scheduleAutoCheck(STARTUP_CHECK_DELAY_MS)
    if (schedulerTimer !== null) clearInterval(schedulerTimer)
    schedulerTimer = setInterval(runSchedulerTick, SCHEDULER_TICK_MS)
  }, [])

  /**
   * User-initiated check. Unlike the automatic path it always answers on
   * screen, and it downloads eagerly so that "Restart now" is instant.
   */
  const checkForUpdates = useCallback(async (): Promise<CheckOutcome> => {
    const store = useGanymedeStore.getState()

    if (!isTauri()) {
      store.setUpdateError('Updates only available in desktop app', true)
      return 'failed'
    }

    // Something is already in flight or waiting: show it rather than start over.
    if (store.updateFlowBusy || (store.updatePhase !== 'idle' && store.updatePhase !== 'error')) {
      store.surfaceUpdate()
      return 'pending'
    }

    store.setUpdateFlowBusy(true)
    store.setUpdateChecking()

    try {
      const { check } = await import('@tauri-apps/plugin-updater')
      const update = (await check()) as TauriUpdate | null

      if (!update) {
        useGanymedeStore.getState().setUpdateIdle()
        console.log('[Updater] Already on latest version')
        return 'up-to-date'
      }

      // The round trip is long enough for the scheduler to have opened a
      // countdown on a package that was already waiting.
      const { updatePhase } = useGanymedeStore.getState()
      if (updatePhase === 'warning' || updatePhase === 'installing') {
        await releaseHandle(update)
        useGanymedeStore.getState().surfaceUpdate()
        return 'pending'
      }

      await discardPending()
      pendingUpdate = update
      console.log('[Updater] Update found:', update.version)

      await downloadPending(update, true)
      useGanymedeStore.getState().setUpdateScheduled(nextLocalMidnight(new Date()))
      return 'pending'
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Update check failed'
      console.error('[Updater] Check failed:', message)
      await discardPending()
      useGanymedeStore.getState().setUpdateError(message, true)
      return 'failed'
    } finally {
      useGanymedeStore.getState().setUpdateFlowBusy(false)
    }
  }, [])

  const restartNow = useCallback(async (): Promise<void> => {
    await applyUpdate({ surfaceErrors: true })
  }, [])

  /** Move the restart to the night after the one currently planned. */
  const postpone = useCallback((): void => {
    const store = useGanymedeStore.getState()
    const restartAt = nextLocalMidnight(new Date(store.updateRestartAt ?? Date.now()))
    store.setUpdateScheduled(restartAt)
    store.hideUpdateBanner()
    console.log('[Updater] Restart postponed to', new Date(restartAt).toISOString())
  }, [])

  /** Put the banner away. The planned restart is untouched. */
  const dismiss = useCallback((): void => {
    useGanymedeStore.getState().hideUpdateBanner()
  }, [])

  return {
    ...state,
    checkForUpdates,
    restartNow,
    postpone,
    dismiss,
  }
}

  }
}

