 * for one. Those go straight out.
 *
 * Returns whether the toast was actually handed to the OS, so a caller whose
 * flow depends on the user having been warned can react when it was not.
 */
export async function sendUrgentNativeNotification(
  options: NativeNotificationOptions
): Promise<boolean> {
  if (!isTauri()) return false

  const granted = await requestNotificationPermission()
  if (!granted) {
    console.warn('[NativeNotification] Urgent toast suppressed: permission not granted')
    return false
  }

  return dispatchToast(options)
